const raw = $input.first().json.output_text || '{}';
let plan; try { plan = JSON.parse(raw); } catch(e) { throw new Error('Cannot parse scene plan: ' + raw.slice(0, 300)); }
const base = $('Code - Parse Claude Refinement').first().json;
return [{ json: { ...base, scene_plan: plan, scenes_count: (plan.scenes || []).length } }];

const base = $input.first().json;
const scenes = base.scene_plan.scenes || [];
return scenes.map(scene => ({
  json: {
    episode_id: base.episode_id,
    workspace: base.workspace,
    title: base.script.title,
    narration_script: base.script.narration_script,
    thumbnail_text: base.topic.thumbnail_text,
    seo_keywords: base.topic.seo_keywords,
    style_bible: base.scene_plan.style_bible,
    scene
  }
}));

