const base = $('Code - Split Scenes').all()[$itemIndex]?.json || {};
const img = $input.first().json;
const url = img.data?.[0]?.url || null;
return [{ json: { ...base, image_url: url } }];

const items = $input.all().map(i => i.json);
if (!items.length) throw new Error('No scene items to build manifest');
const base = items[0];

const manifest = {
  episode_id: base.episode_id,
  workspace: base.workspace,
  title: base.title,
  narration_script: base.narration_script,
  thumbnail_text: base.thumbnail_text,
  seo_keywords: base.seo_keywords || [],
  scenes: items.map(item => ({
    scene_id: String(item.scene.scene_id),
    start_sec: item.scene.start_sec || 0,
    end_sec: item.scene.end_sec || parseInt($env.SCENE_VIDEO_SECONDS || '8'),
    narration_excerpt: item.scene.narration_excerpt || '',
    image: item.image_url || null,
    video_prompt: item.scene.video_prompt || item.scene.image_prompt || '',
    sound_design: item.scene.sound_design || 'ambient'
  }))
};
return [{ json: manifest }];

